+// API keys and roles. Pure rules over the store; the HTTP layer calls these.
+import { AppError } from "../errors.js";
+
+/** Roles from least to most powerful. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// Routes a cook may call besides reading.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Reads only managers may make.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** Finds the API key record for an Authorization header value, or throws unauthorized. */
+export function authenticate(store, header) {
+  const m = /^Bearer\s+(\S+)$/i.exec(typeof header === "string" ? header.trim() : "");
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws forbidden unless `role` may call the route `method` + `pattern`. */
+export function authorize(role, method, pattern) {
+  const route = `${method} ${pattern}`;
+  const ok =
+    role === "manager" ||
+    (role === "viewer" && method === "GET" && !MANAGER_READS.has(route)) ||
+    (role === "cook" && ((method === "GET" && !MANAGER_READS.has(route)) || COOK_ROUTES.has(route)));
+  if (!ok) throw new AppError("forbidden", { role });
+}
